-- Backfill profiles for users registered before the migration.
insert into public.profiles(id) select id from auth.users on conflict(id) do nothing;
-- Preferences + notification settings are committed together.
create function public.save_preferences(p_preferences jsonb) returns void language plpgsql security invoker set search_path=public as $$ begin
 if auth.uid() is null then raise exception 'unauthorized'; end if;
 insert into user_preferences(user_id,nutrition_track,goals,time_budget_minutes,activity_level,equipment,excluded_exercises,food_allergies,limitations,cold_opt_in,cold_safety_ack,safety_ack) values(auth.uid(),p_preferences->>'nutrition_track',p_preferences->'goals',(p_preferences->>'time_budget_minutes')::int,p_preferences->>'activity_level',p_preferences->'equipment',p_preferences->'excluded_exercises',p_preferences->'food_allergies',p_preferences->>'limitations',(p_preferences->>'cold_opt_in')::boolean,(p_preferences->>'cold_safety_ack')::boolean,(p_preferences->>'safety_ack')::boolean) on conflict(user_id) do update set nutrition_track=excluded.nutrition_track,goals=excluded.goals,time_budget_minutes=excluded.time_budget_minutes,activity_level=excluded.activity_level,equipment=excluded.equipment,excluded_exercises=excluded.excluded_exercises,food_allergies=excluded.food_allergies,limitations=excluded.limitations,cold_opt_in=excluded.cold_opt_in,cold_safety_ack=excluded.cold_safety_ack,safety_ack=excluded.safety_ack,updated_at=now();
 insert into notification_preferences(user_id,reminders_enabled,preferred_local_time) values(auth.uid(),(p_preferences->>'reminders_enabled')::boolean,p_preferences->>'preferred_local_time') on conflict(user_id) do update set reminders_enabled=excluded.reminders_enabled,preferred_local_time=excluded.preferred_local_time;
 update user_programs set template_id=(select id from program_templates where slug='starter-'||(p_preferences->>'nutrition_track') and published limit 1) where user_id=auth.uid() and status='active' and exists(select 1 from program_templates where slug='starter-'||(p_preferences->>'nutrition_track') and published);
end $$;
revoke all on function public.save_preferences(jsonb) from public,anon;grant execute on function public.save_preferences(jsonb) to authenticated;
